{"explanation":"In y = a(x − h)² + k, h moves the parabola left or right, and k moves it up or down, placing the vertex at (h, k) when a ≠ 0. The coefficient a controls its shape: positive opens upward, negative opens downward, and larger |a| makes it narrower. Explore the sliders; when a = 0, the graph becomes the horizontal line y = k.","manimCode":"const heading = new Text({ text: 'Shape and position of a parabola', fontSize: 30, color: WHITE });
heading.moveTo([0, 3.25, 0]);
const equation = new MathTex({ latex: 'y = a(x-h)^2 + k', color: WHITE });
await equation.waitForRender();
equation.moveTo([-0.9, 2.55, 0]);

const ax = new Axes({
  xRange: [-6, 6, 2],
  yRange: [-6, 6, 2],
  xLength: 9,
  yLength: 4.6,
  tips: false
});
ax.moveTo([-0.9, -0.25, 0]);

let coefficient = 1;
let horizontal = 0;
let vertical = 0;
let curve;
let status;
const vertex = new Dot({ point: ax.c2p(0, 0), color: YELLOW });

function buildCurve() {
  let leftEdge = -6;
  let rightEdge = 6;
  if (Math.abs(coefficient) > 0.000001) {
    const availableHeight = coefficient > 0 ? 6 - vertical : vertical + 6;
    const reach = Math.sqrt(availableHeight / Math.abs(coefficient));
    leftEdge = Math.max(-6, horizontal - reach);
    rightEdge = Math.min(6, horizontal + reach);
  }
  return ax.plot(x => coefficient * (x - horizontal) ** 2 + vertical, {
    xRange: [leftEdge, rightEdge],
    numSamples: 350,
    color: BLUE,
    strokeWidth: 4
  });
}

function updateStatus() {
  if (status) scene.remove(status);
  let description;
  if (Math.abs(coefficient) < 0.000001) {
    description = 'a = 0: horizontal line y = ' + vertical.toFixed(1) + ' (no unique vertex)';
  } else {
    const opening = coefficient > 0 ? 'opens up' : 'opens down';
    const magnitude = Math.abs(coefficient);
    const widthDescription = magnitude > 1.001 ? 'narrower' : magnitude < 0.999 ? 'wider' : 'standard width';
    description = 'Vertex (' + horizontal.toFixed(1) + ', ' + vertical.toFixed(1) + ')  |  ' + opening + '  |  ' + widthDescription;
  }
  status = new Text({ text: description, fontSize: 22, color: YELLOW });
  status.moveTo([-0.5, -3.15, 0]);
  scene.add(status);
}

function refresh() {
  scene.remove(curve);
  curve = buildCurve();
  scene.add(curve);
  vertex.moveTo(ax.c2p(horizontal, vertical));
  vertex.setOpacity(Math.abs(coefficient) < 0.000001 ? 0 : 1);
  scene.remove(vertex);
  scene.add(vertex);
  updateStatus();
}

await scene.play(new AnimationGroup([new Write(heading), new FadeIn(equation), new Create(ax)]));
curve = buildCurve();
await scene.play(new Create(curve));
scene.add(vertex);
updateStatus();
makeHoverable(vertex, scene, { hoverScale: 1.5, hoverColor: ORANGE });

const controls = new Controls(scene, { position: 'top-right', theme: 'dark', width: 250 });
controls.addSlider({
  label: 'a: opening and width', min: -2, max: 2, step: 0.1, value: 1,
  onChange: value => { coefficient = value; refresh(); }
});
controls.addSlider({
  label: 'h: horizontal shift', min: -3, max: 3, step: 0.1, value: 0,
  onChange: value => { horizontal = value; refresh(); }
});
controls.addSlider({
  label: 'k: vertical shift', min: -3, max: 3, step: 0.1, value: 0,
  onChange: value => { vertical = value; refresh(); }
});
await scene.wait(999999);"}

